import 'package:flutter/material.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../auth/screens/account_screen.dart';
import '../auth/services/auth_service.dart';
import '../dashboard/screens/dashboard_screen.dart';
import '../map_disposal/screens/map_disposal_screen.dart';
import '../sync_alerts/screens/sync_alerts_screen.dart';

/// Owned by the tech lead. Feature developers do not edit this file — their
/// screens are already wired here. Adding a tab is a lead-level change.
class MainNavigationScreen extends StatefulWidget {
  const MainNavigationScreen({
    super.key,
    required this.auth,
    required this.user,
  });

  final AuthService auth;
  final User user;

  @override
  State<MainNavigationScreen> createState() => _MainNavigationScreenState();
}

class _MainNavigationScreenState extends State<MainNavigationScreen> {
  int _index = 0;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      // IndexedStack keeps each tab alive, so scroll position and form state
      // survive a tab switch.
      body: IndexedStack(
        index: _index,
        children: [
          const DashboardScreen(),
          const MapDisposalScreen(),
          const SyncAlertsScreen(),
          AccountScreen(auth: widget.auth, user: widget.user),
        ],
      ),
      bottomNavigationBar: NavigationBar(
        selectedIndex: _index,
        onDestinationSelected: (index) => setState(() => _index = index),
        destinations: const [
          NavigationDestination(
            icon: Icon(Icons.dashboard_outlined),
            selectedIcon: Icon(Icons.dashboard),
            label: 'Pantry',
          ),
          NavigationDestination(
            icon: Icon(Icons.map_outlined),
            selectedIcon: Icon(Icons.map),
            label: 'Dispose',
          ),
          NavigationDestination(
            icon: Icon(Icons.notifications_outlined),
            selectedIcon: Icon(Icons.notifications),
            label: 'Alerts',
          ),
          NavigationDestination(
            icon: Icon(Icons.person_outline),
            selectedIcon: Icon(Icons.person),
            label: 'Account',
          ),
        ],
      ),
    );
  }
}
